#!/usr/bin/env node
/**
 * Reads content/guides/*.mdx and writes lib/guides.generated.ts with the parsed
 * guides inlined so the runtime never needs node:fs. Cloudflare Workers has no
 * filesystem, so doing this at request time stalls /guides in a Suspense fallback.
 * Keep MDX as the source of truth; this file is generated by `prebuild` and `predev`.
 */
import { readdirSync, readFileSync, mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";

const root = process.cwd();
const dir = path.join(root, "content", "guides");
const out = path.join(root, "lib", "guides.generated.ts");

function parseFrontmatter(slug, raw) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/.exec(raw);
  if (!match) throw new Error(`Guide ${slug} has no frontmatter`);
  const fields = {};
  for (const line of match[1].split(/\r?\n/)) {
    const i = line.indexOf(":");
    if (i > 0) fields[line.slice(0, i).trim()] = line.slice(i + 1).trim();
  }
  const { title, description, region, published } = fields;
  if (!title || !description || !region || !published) {
    throw new Error(`Guide ${slug} is missing frontmatter fields`);
  }
  return { slug, title, description, region, published, body: match[2].trim() };
}

const files = readdirSync(dir)
  .filter((f) => f.endsWith(".mdx"))
  .sort();

const guides = files.map((f) => {
  const slug = f.replace(/\.mdx$/, "");
  return parseFrontmatter(slug, readFileSync(path.join(dir, f), "utf8"));
});

const body = `// AUTO-GENERATED by scripts/build-guides.mjs. Do not edit by hand.
// Source: content/guides/*.mdx. Re-run with \`node scripts/build-guides.mjs\`.

export type GeneratedGuide = {
  slug: string;
  title: string;
  description: string;
  region: string;
  published: string;
  body: string;
};

export const GUIDES: readonly GeneratedGuide[] = ${JSON.stringify(guides, null, 2)} as const;
`;

mkdirSync(path.dirname(out), { recursive: true });
writeFileSync(out, body, "utf8");
console.log(`wrote ${out} (${guides.length} guides)`);
